import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Navbar.css';

function Navbar({ cartCount, onCartClick, user, onLogout }) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const navigate = useNavigate();

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link to="/" className="navbar-brand" onClick={() => setIsMenuOpen(false)}>
          <span className="brand-icon">🍛</span>
          <div className="brand-text">
            <span className="brand-name">Riddhi Siddhi</span>
            <span className="brand-tagline">Modak Farsan</span>
          </div>
        </Link>

        <button
          className={`menu-toggle ${isMenuOpen ? 'active' : ''}`}
          onClick={() => setIsMenuOpen(!isMenuOpen)}
          aria-label="Toggle menu"
        >
          <span></span>
          <span></span>
          <span></span>
        </button>

        <div className={`navbar-menu ${isMenuOpen ? 'active' : ''}`}>
          <Link to="/" className="nav-link" onClick={() => setIsMenuOpen(false)}>
            <span className="nav-icon">🏠</span> Home
          </Link>
          <Link to="/category/dry" className="nav-link" onClick={() => setIsMenuOpen(false)}>
            <span className="nav-icon">🥨</span> Dry Items
          </Link>
          <Link to="/category/sweet" className="nav-link" onClick={() => setIsMenuOpen(false)}>
            <span className="nav-icon">🍬</span> Sweets
          </Link>
          <Link to="/category/wet" className="nav-link" onClick={() => setIsMenuOpen(false)}>
            <span className="nav-icon">🍮</span> Fresh Sweets
          </Link>
          {user ? (
            <>
              <Link to="/dashboard" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                <span className="nav-icon">📋</span> Orders
              </Link>
              <button className="nav-link nav-btn" onClick={() => {
                onLogout();
                setIsMenuOpen(false);
                navigate('/');
              }}>
                <span className="nav-icon">🚪</span> Logout
              </button>
            </>
          ) : (
            <Link to="/checkout" className="nav-link" onClick={() => setIsMenuOpen(false)}>
              <span className="nav-icon">👤</span> Login
            </Link>
          )}
        </div>

        <button className="cart-button" onClick={onCartClick} aria-label="Open cart">
          <span className="cart-icon">🛒</span>
          {cartCount > 0 && <span className="cart-badge">{cartCount}</span>}
        </button>
      </div>
    </nav>
  );
}

export default Navbar;
